const UiStr* AR_GetStrTable( int ovlId, int* n )
{
	switch( ovlId ){
		case OVL_UI:            *n = countRows(AR_Ui);           return AR_Ui;
		case OVL_MENU:          *n = countRows(AR_Menu);         return AR_Menu;
		case OVL_UNIQUE_ITEM:   *n = countRows(AR_UniqueItem);   return AR_UniqueItem;
		case OVL_AFFIX_PREFIX:  *n = countRows(AR_AffixPrefix);  return AR_AffixPrefix;
		case OVL_AFFIX_SUFFIX:  *n = countRows(AR_AffixSuffix);  return AR_AffixSuffix;
		case OVL_BASE_ITEM:     *n = countRows(AR_BaseItem);     return AR_BaseItem;
		case OVL_BASE_NAME2:    *n = countRows(AR_BaseName2);    return AR_BaseName2;
		case OVL_ELEMENT:       *n = countRows(AR_Element);      return AR_Element;
		case OVL_SPICIES:       *n = countRows(AR_Spicies);      return AR_Spicies;
		case OVL_ICEAGE:        *n = countRows(AR_IceAge);       return AR_IceAge;
		case OVL_SPELL:         *n = countRows(AR_Spell);        return AR_Spell;
		case OVL_SPELL_NOM:     *n = countRows(AR_SpellNom);     return AR_SpellNom;
		case OVL_PERK_NAME:     *n = countRows(AR_PerkName);     return AR_PerkName;
		case OVL_PERK_DESC:     *n = countRows(AR_PerkDesc);     return AR_PerkDesc;
		case OVL_WARP:          *n = countRows(AR_Warp);         return AR_Warp;
		case OVL_WARP_OBL:      *n = countRows(AR_WarpOblique);  return AR_WarpOblique;
	}
	*n = 0; return nullptr;
}

const IdxStr* AR_GetIdxTable( int ovlId, int* n )
{
	switch( ovlId ){
		case OVL_SPEECH:   *n = countRows(AR_Speech);   return AR_Speech;
		case OVL_ONSCREEN: *n = countRows(AR_OnScreen); return AR_OnScreen;
		case OVL_QUEST:    *n = countRows(AR_Quest);    return AR_Quest;
	}
	*n = 0; return nullptr;
}

